const item = $input.first().json;
const body = item.text || item.snippet || item.body || item.textPlain || '';

function parseField(text, ...names) {
  for (const name of names) {
    const escaped = name.replace(/[-]/g, '\\-');
    const match = text.match(new RegExp(escaped + ':\\s*(.+)', 'im'));
    if (match) return match[1].trim();
  }
  return '';
}

const companyName = parseField(body, 'Unternehmensname', 'Firma', 'Unternehmen');
const industry = parseField(body, 'Branche', 'Industry');
const websiteRaw = parseField(body, 'Website', 'Webseite');
const logoInfo = parseField(body, 'Logo');
const logoFaceliftRaw = parseField(body, 'Logo-Facelift', 'Facelift', 'Logo Facelift');
const region = parseField(body, 'Region', 'Ort', 'Standort');
const services = parseField(body, 'Leistungen', 'Services', 'Angebote');
const targetGroup = parseField(body, 'Zielgruppe', 'Kunden', 'Zielgruppe');
const style = parseField(body, 'Stil', 'Style', 'Design', 'Stilwunsch');

// Build URL-safe slug from company name
const slug = (companyName || 'demo')
  .toLowerCase()
  .replace(/\u00e4/g, 'ae').replace(/\u00f6/g, 'oe')
  .replace(/\u00fc/g, 'ue').replace(/\u00df/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '') || 'demo';

const noWebsiteValues = ['keine', 'kein', 'nein', 'no', 'none', '-', ''];
const hasWebsite = !!websiteRaw &&
  !noWebsiteValues.includes(websiteRaw.toLowerCase()) &&
  websiteRaw.startsWith('http');

const noLogoValues = ['kein', 'keine', 'facelift', 'nein', 'no', 'none', '-', ''];
const logoUrl = (!!logoInfo &&
  !noLogoValues.includes(logoInfo.toLowerCase()) &&
  logoInfo.startsWith('http')) ? logoInfo : null;

const logoFacelift = ['ja', 'yes', 'true', '1'].includes((logoFaceliftRaw || '').toLowerCase());

const fromAddr = item.from?.email || (typeof item.from === 'string' ? item.from : '') || '';

return [{
  json: {
    companyName,
    industry,
    websiteUrl: hasWebsite ? websiteRaw : null,
    logoUrl,
    logoFacelift,
    region,
    services,
    targetGroup,
    style,
    slug,
    previewUrl: `https://www.hannahs-webdesign.de/${slug}/`,
    remotePath: `/httpdocs/${slug}`,
    hasWebsite,
    hasLogo: !!logoUrl,
    fromEmail: fromAddr,
    crawledContent: ''
  }
}];

const html = $input.first().json.data || $input.first().json.body || '';
const companyData = $('Parse Email Data').first().json;

// Strip HTML, extract readable text
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n').replace(/<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"')
  .replace(/[ \t]+/g, ' ')
  .split('\n').map(l => l.trim()).filter(l => l.length > 20)
  .join('\n')
  .substring(0, 5000);

// Find up to 3 internal subpage links
const baseUrl = companyData.websiteUrl || '';
const baseHost = (baseUrl.match(/^https?:\/\/([^/]+)/) || [])[1] || '';
const linkRe = /href=["']([^"'#?]+)["']/g;
const links = [];
let m;
while ((m = linkRe.exec(html)) !== null && links.length < 5) {
  const href = m[1];
  if (!href || href.length < 2) continue;
  const full = href.startsWith('http') ? href
    : `${baseUrl.replace(/\/$/, '')}/${href.replace(/^\//, '')}`;
  if (full.includes(baseHost) && !links.includes(full) && full !== baseUrl
      && !full.match(/\.(jpg|jpeg|png|gif|pdf|svg|ico|css|js)/i)) {
    links.push(full);
  }
}

const crawledContent = text
  ? `Bestehende Website (${baseUrl}):\n${text}\n`
  : '';

return [{
  json: {
    ...companyData,
    crawledContent,
    subpageLinks: links.slice(0, 3)
  }
}];

const subHtml = $input.first().json.data || '';
const prev = $('Content extrahieren').first().json;

const subText = subHtml
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/[ \t]+/g, ' ')
  .split('\n').map(l => l.trim()).filter(l => l.length > 20)
  .join('\n')
  .substring(0, 2000);

const combined = prev.crawledContent + (subText ? `\nWeitere Unterseiten:\n${subText}` : '');

return [{
  json: {
    ...prev,
    crawledContent: combined.substring(0, 6000)
  }
}];

