const d = $('Parse Email Data').first().json;
const company = d.companyName;
const industry = d.industry;
const region = d.region;
const services = d.services;
const style = d.style;

const baseStyle = 'photorealistic, professional quality, 16:9 format, high resolution, no text, no watermark';

const prompts = [
  `Hero image: ${industry} professional business in ${region}, modern exterior or team photo, impressive, cinematic lighting, ${baseStyle}`,
  `Professional team of ${industry} workers, friendly smiling, modern work environment, authentic German business, ${baseStyle}`,
  `Close-up detail shot of ${services.split(',')[0]?.trim() || industry} work, high quality craftsmanship, professional tools, ${baseStyle}`,
  `Satisfied customer consultation, ${industry} professional presenting results, trust and expertise, ${baseStyle}`,
  `Modern office or workspace interior, ${industry} company, clean and organized, ${baseStyle}`,
  `Before-after or finished project result for ${industry}, impressive quality, ${baseStyle}`,
  `Regional cityscape or landmark of ${region}, business context, golden hour, ${baseStyle}`,
  `${industry} technology and modern equipment, innovation, professional setting, ${baseStyle}`,
  `Team collaboration, ${industry} planning meeting, whiteboard or blueprints, professional, ${baseStyle}`,
  `Abstract concept representing excellence and reliability in ${industry}, modern minimalist, ${style.split(',')[0] || 'professional'} color palette, ${baseStyle}`
];

return prompts.map((prompt, i) => ({
  json: {
    imageIndex: i + 1,
    filename: `image-${String(i + 1).padStart(2, '0')}.jpg`,
    prompt,
    slug: d.slug,
    remotePath: d.remotePath
  }
}));

const d = $('Parse Email Data').first().json;
const idxResp = $('Index HTML generieren (Groq)').first().json;
const angResp = $('Angebot HTML generieren (Groq)').first().json;
const cssResp = $('CSS generieren (Groq)').first().json;

const indexHtml = (idxResp.choices?.[0]?.message?.content || '')
  .replace(/^```html?
?/, '').replace(/
?```$/, '').trim();

const angebotHtml = (angResp.choices?.[0]?.message?.content || '')
  .replace(/^```html?
?/, '').replace(/
?```$/, '').trim();

const cssContent = (cssResp.choices?.[0]?.message?.content || '')
  .replace(/^```css?
?/, '').replace(/
?```$/, '').trim();

const logoSection = d.hasLogo
  ? (d.logoFacelift
      ? '- logo.png           : Ihr bestehendes Logo
- logo-concept-1.jpg : Logo-Konzept 1 (KI-generiert)
- logo-concept-2.jpg : Logo-Konzept 2 (KI-generiert)
- logo-concept-3.jpg : Logo-Konzept 3 (KI-generiert)'
      : '- logo.png           : Ihr Logo')
  : (d.logoFacelift
      ? '- logo-concept-1.jpg : Logo-Konzept 1 (KI-generiert)
- logo-concept-2.jpg : Logo-Konzept 2 (KI-generiert)
- logo-concept-3.jpg : Logo-Konzept 3 (KI-generiert)'
      : '');

const now = new Date().toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });

const readmeTxt = `DEMO-WEBSITE VORSCHAU
${"=".repeat(60)}

Unternehmen : ${d.companyName}
Branche     : ${d.industry}
Region      : ${d.region}
Erstellt    : ${now}

Vorschau-URL:
${d.previewUrl}

${"=".repeat(60)}
ENTHALTENE DATEIEN
${"=".repeat(60)}

- index.html         : Haupt-Demo-Seite
- angebot.html       : Angebotsseite (CTA)
- styles.css         : Stylesheet
- image-01.jpg bis image-10.jpg : KI-generierte Fotos
${logoSection}

${"=".repeat(60)}
HANNAH'S WEBDESIGN
${"=".repeat(60)}

Diese Demo wurde automatisch erstellt von:
Hannah's Webdesign
https://www.hannahs-webdesign.de
info@hannahs-webdesign.de

Fuer das vollstandige Website-Paket:
-> ${d.previewUrl}angebot.html
`;

return [{
  json: {
    ...d,
    indexHtml,
    angebotHtml,
    cssContent,
    readmeTxt
  }
}];

const d = $input.first().json;
return [{
